class Duration:
    def __init__(self, minutes):
        self.minutes = minutes

    @property
    def minutes(self):
        return self._minutes

    @minutes.setter
    def minutes(self, value):
        if value < 0:
            raise ValueError("minutes must be nonnegative")
        self._minutes = value

duration = Duration(10)
print(duration.minutes)
duration.minutes = 15
print(duration.minutes)
try:
    duration.minutes = -1
except ValueError:
    print(duration.minutes)
